def split_into_gcd_groups(numbers):
    temp_gcd = numbers[0]
    for i in range(1, len(numbers)):
        temp_gcd = gcd(temp_gcd, numbers[i])
        if temp_gcd == 1:
            break
        if temp_gcd == 0:
