    temp_gcd = numbers[1]
    for i in range(1, len(numbers) - 1):
        temp_gcd = gcd(temp_gcd, numbers[i+1])
        if temp_gcd == 1:
            break
        if temp_gcd == 0:
            return []
    else:
        return [[1] + [2]*len(numbers)]

    return [[1]*len(numbers)]

