from collections import defaultdict

def solve(tree):
    total_cost = 0
    nodes = len(tree)
    for l in tree.values():
        total_cost += l
    new_tree = defaultdict(int)
    for node, values in tree.items():
        new_tree[node] += values[0] + values[1]
    total_cost += sum([k * v for k, v in new_tree.items()])
    for l in tree.values():
        for node in l:
            l[0] += new_tree.get(node, 0)
    return total_cost * (2 / nodes)

