from collections import defaultdict, deque

def can_perform_warping(N, M, roads, target_warps):
    parents = [i for i in range(N + 1)]
    rank = [0 for _ in range(N + 1)]
    components = []

    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] < rank[root_y]:
                root_x, root_y = root_y, root_x
            rank[root_x] += 1
            parents[root_y] = root_x

    for s, e in roads:
        union(s, e)

    for s, e in target_warps:
        if find(s) != find(e):
            components.append(set([s, e]))

    if not components:
        return "YES"

    max_edges = sum(len(c) for c in components) // 2

    max_edges = min(max_edges, M - len(target_warps))

    required_roads = set()
    cycle_edges = set()

    for u, v in components:
        for parent in parents[u: v + 1]:
            required_roads.add((u, parent))
            cycle_edges.add((u, v))

    required_roads = required_roads - cycle_edges

    if len(required_roads) <= max_edges:
        return "YES"

    return "NO"

