class ChessBoard:

    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.boards = [None] * (2*n + 1) * (2*m + 1)

    def mark_cell(self, i, j):
        cell_index = self.fourth_index_to_i_j(i, j)

        if self.boards[cell_index] is None:
            self.boards[cell_index] = "unavailable"
            return "YES"
        else:
            self.boards[cell_index] = "available"
            return "NO"

    def four_index_to_i_j(self, four_index):
        i_n = four_index // (4 * (2 * self.m + 1))
        i_r = four_index // 4 % (2 * self.m + 1) // 2
        j_m = four_index - 4 * i_n * (2 * self.m + 1)
        j_r = j_m // 2 % (2 * self.n + 1)
        return i_r + i_n + self.n

    def i_j_to_four_index(self, i, j):
        first_i = self.calculate_first_i(i)
        first_j = self.calculate_first_j(j)
        first_i_to_four_index = first_i - first_j + first_j // 2

        if not first_j % 2:
            fourth_j = 2 * first_j + self.n - self.n // 2
            four_index = 4 * first_i % (4 * (2 * self.m + first_j)) + first_j + self.m
        else:
            fourth_j = 2 * first_j + 1 - self.n // 2
            four_index = 4 * first_i % (4 * (2 * self.m + first_j)) + first_j + 1 + self.m

        return four_index - (4 * first_j - fourth_j * 4 // 2) * first_j // 2

    def calculate_first_i(self, i):
        cell_index = self.fourth_index_to_i_j(i, 1)
        if self.boards[cell_index] == "unavailable":
            return i
        else:
            return self.calculate_first_i(i - 2)

    def calculate_first_j(self, j):
        cell_index = self.fourth_index_to_i_j(1, j)
        if self.boards[cell_index] == "unavailable":
            return j
        else:
            return self.calculate_first_j(j - 2)

