import math
from collections import defaultdict

def read_input():
    n, k = map(int, input().split())
    prerequisites = list(map(int, input().split()))
    special_pairs = []
    for _ in range(k):
        x, y = map(int, input().split())
        prerequisites[x-1] = y-1
        special_pairs.append((x, y))
    return n, k, prerequisites, special_pairs

def is_valid_ordering(ordering, prerequisites, special_pairs):
    for x, y in special_pairs:
        if ordering.index(x) > ordering.index(y):
            return False
    return True

def find_solution(n, k, prerequisites, special_pairs):
    solutions = set()
    for ordering in permutations(range(1, n+1)):
        if is_valid_ordering(ordering, prerequisites, special_pairs):
            solutions.add(ordering)
    if solutions:
        return solutions.pop()
    return 0

if __name__ == "__main__":
    n, k = read_input()
    prerequisites, special_pairs = read_input()
    ordering = find_solution(n, k, prerequisites, special_pairs)
    if ordering:
        print(ordering)
    else:
        print(0)
