# 10^9 + 7 is the same as 1000000007 in decimal
mod = 1000000007

def find_frontway():
    return random.choice(['F', 'B'])

def find_backway():
    return random.choice(['F', 'B'])

def find_free_seat(entrance, seat):
    choices = [seat, (seat + 1000000) % 1000000]
    choices.sort()
    target = choices[(entrance - 1) % 2] if entrance != 1 else choices[0]
    count = 0
    while choices[count] < target:
        count += 1
        if choices[count] == target:
            return choices[count]
    else:
        return choices[count % 2]

def calculate_ways():
    total_ways = 0
    for _, entrance in itertools.product(['F', 'B'], repeat=(n + 1)//2):
        free_seats = [(f, find_free_seat(entrance, f)) for f in range(n)]
        room_ways = 1
        empty_seat = find_free_seat(0, free_seats[0][0])
        has_taken_after_free = 0
        for f, seat in free_seats:
            if seat == empty_seat:
                has_taken_after_free = 1
                continue
            if f == 0 and seat == empty_seat:
                room_ways = (room_ways * (1 + has_taken_after_free)) % mod
            else:
                room_ways = (room_ways * (has_taken_after_free - has_taken_after_free ** 2)) % mod
            empty_seat = find_free_seat(1 - entrance, empty_seat)
        total_ways = (total_ways * room_ways) % mod
    return total_ways

