def split_numbers(n, a):
    max_gcd = gcd(a[0], a[1])

    if gcd(a[0], a[1]) != max_gcd:
        return False

    cnt = [0] * 2
    for num in a:
        if gcd(num, max_gcd) == max_gcd:
            cnt[1] += 1
        else:
            cnt[0] += 1

    if cnt[0] + cnt[1] > 1:
        return False

    if cnt[0] > 0:
        return "YES"
    else:
        return "NO"

