import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def compute_distance_matrix(n):
    distance_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            distance = math.sqrt(abs(i - j))
            common_divisor = math.gcd(i, j)
            if common_divisor > 0:
                distance /= common_divisor
            distance_matrix[i][j] = distance_matrix[j][i] = distance
    return distance_matrix

def compute_cost_matrix(distance_matrix):
    cost_matrix = [[0] * len(distance_matrix) for _ in range(len(distance_matrix))]
    for i in range(len(distance_matrix)):
        cost_matrix[i][i] = 0
    for k in range(len(distance_matrix)):
        for i in range(len(distance_matrix)):
            for j in range(len(distance_matrix)):
                cost_matrix[i][j] = min(cost_matrix[i][j], distance_matrix[i][k] + distance_matrix[k][j])
    return cost_matrix

def sum_of_distances(n):
    distance_matrix = compute_distance_matrix(n)
    cost_matrix = compute_cost_matrix(distance_matrix)
    return sum(cost_matrix[i][j] for i in range(n) for j in range(i + 1, n))

