def modsum(n, m, queries):
    A = [0] * (n + 1)
    for i in range(1, n + 1):
        A[i] = i

    current_mod = 0
    for query in queries:
        if query[0] == 1:
            l, r = query[1] - 1, query[2] - 1
            for i in range(l, r + 1):
                A[i] = (A[i] + current_mod) % m
        else:
            l, r = query[1] - 1, query[2] - 1
            current_mod += A[r + 1] - A[l]
            current_mod %= m

    return sum(A[1:r + 1] for r in range(n + 1))

