from typing import List, Tuple

def find_path(m: List[List[int]]) -> List[Tuple[int, int]]:
    n = len(m)
    edges = [[True] * n for _ in range(n)]

    for i in range(n):
        lists = m[i]
        for j in range(n):
            if i != j and j in lists:
                edges[i][j] = False

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if edges[i][k] and edges[k][j]:
                    edges[i][j] = True
                    edges[j][i] = True

    visited = set()
    res = []
    for i in range(n):
        if i not in visited:
            path = [i]
            visited.add(i)
            while True:
                temp = []
                for j in range(n):
                    if (i, j) in edges:
                        temp.append(j)
                if not temp:
                    break
                curr = temp.pop()
                if curr not in visited:
                    visited.add(curr)
                    path.append(curr)
                    edges[curr][i] = False
                    for k in range(n):
                        if edges[i][k]:
                            edges[i][k] = False
                            edges[k][i] = False
            if len(path) > 1:
                res.append((path[0], path[-1]))

    if len(res) == n - 1:
        return res
    else:
        return [-1]

