from collections import deque

def find_sequences(dp, blocks, n):
    # Initialize a maximum value deque
    max_value_deque = deque([0])

    for i in range(n):
        new_deque = deque()
        for block in dp[i]:
            max_value_deque.append(max(block.value, block.value + max_value_deque.popleft()))
            new_block = []
            if block.flip is not None:
                new_block.append(block.flip[1] | block.value | block.flip[0])
            else:
                new_block.append(block.value)
            if len(new_deque) < 2 or new_block[0] >= new_deque[-1]:
                new_deque.append(new_block)

        dp[i + 1] = deque(new_deque)

    return max(dp[-1])

def process_file(filename):
    with open(filename, "r") as file:
        n = int(file.readline())
        dp = [None] * (n + 1)
        blocks = deque()

        for _ in range(n):
            block = deque()
            block.append([int(x) for x in file.readline().split()])
            for i in range(2):
                block.append([int(x) for x in file.readline().split()])
            blocks.append(block)

        max_value = 0
        for _ in range(2):
            max_value += blocks.popleft().value

        dp[0] = deque([max_value - blocks.popleft().value])
        while len(blocks) > 1:
            dp.appendleft([])
            max_value = 0
            for i in range(2):
                dp[-1].append(0)
                max_value += dp[i].popleft().value
            for _ in range(2):
                max_value += dp[-1].appendleft(0)
                dp[-1].appendleft(max_value)

        return find_sequences(dp, blocks, n)

def main():
