from collections import defaultdict
from typing import List

class ChessboardGame:
    def __init__(self):
        self.board = defaultdict(bool)
        self.available_cells = {(i, j) for i in range(1, 2*n+1) for j in range(1, 2*m+1) if (i+j) % 2 == 0}

    def mark_cell(self, i: int, j: int) -> None:
        if not self.board[(i, j)]:
            self.available_cells.remove((i, j))
        elif self.board[(i, j)]:
            self.available_cells.add((i, j))

    def is_possible(self, n: int, m: int, queries: List[(int, int)]) -> str:
        self.board.clear()
        self.available_cells = {(i, j) for i in range(1, 2*n+1) for j in range(1, 2*m+1) if (i+j) % 2 == 0}
        for i, j in queries:
            self.mark_cell(i, j)

        if not self.available_cells:
            return "YES"
        else:
            return "NO"

# Example usage
game = ChessboardGame()
print(game.is_possible(1, 3, [(1, 1), (1, 5), (2, 4)]))  # Output: YES
print(game.is_possible(3, 2, [(4, 2), (6, 4), (1, 3), (4, 2), (6, 4), (2, 2), (2, 4), (1, 3), (4, 4), (3, 1)]))  # Output: YES
