def play_game(s, l, r):
    length = len(s)
    alice_turn = True
    board = {}

    for i in range(r - l + 1):
        if alice_turn:
            for char in set(s[i:r + 1]):
                remaining = set(s[i:r + 1]) - {char}
                if remaining:
                    board[char] = remaining if remaining in board else [remaining]
        else:
            for char in set(s[i:r + 1]):
                remaining = set(s[i:r + 1]) - {char}
                if remaining and char not in board and len(sorted(remaining)) > 1:
                    board[char] = remaining if remaining in board else [remaining]

        alice_turn = not alice_turn

    if not board:
        return "Alice" if l == 1 else "Bob"
    else:
        vs = len(list(board))
        return "Alice" if vs % 2 == 1 else "Bob"

# Example usage
