import math
from collections import defaultdict

def sum_distances(n):
    graph = defaultdict(list)
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            graph[u].append(v)
            graph[v].append(u)

    distances = {}
    for u in graph:
        for v in graph[u]:
            distance = math.gcd(u, v)
            distances[(u, v)] = distance

    total_distance = 0
    for u in range(1, n):
        for v in graph[u]:
            total_distance += distances[(u, v)]

    return total_distance

# Example usage
n = 6
print(sum_distances(n))  # Output: 8

n = 10
print(sum_distances(n))  # Output: 44
